def train_step(video, cond):
    t = sample_timestep()
    eps = randn_like(video)
    x_t = sqrt(ab[t]) * video + sqrt(1 - ab[t]) * eps
    pred = unet3d(x_t, t, cond)   # [B,C,T,H,W]
    return mse(pred, eps)

