class MotionModule(nn.Module):
    def forward(self, x):        # x: [B*F, N, D] -> [B, F, N, D]
        x = x.view(B, F, N, D) + sin_pe(F)
        for blk in self.blocks:
            x = blk(x)           # self-attention over F
        return x.view(B*F, N, D)

