def tokenflow(video, prompt_src, prompt_tgt):
    feats = [invert(f, prompt_src) for f in video]
    key = pick_keyframes(feats)
    edited = {k: edit(feats[k], prompt_tgt) for k in key}
    for f in non_keyframes:
        for i, t in enumerate(feats[f]):
            k = nearest_keyframe(t, key)
            feats[f][i] = edited[k][match(t, feats[k])]
    return decode_all(feats)

def rave(video, prompt_src, prompt_tgt, ratio=0.5):
    z = invert(video, prompt_src)
    for t in reversed(timesteps):
        perm = randperm(F)
        z = shuffle_noise(z, perm, ratio)   # 帧间共享噪声
        z = denoise(z, t, prompt_tgt)
    return decode(z)

