def vbench(model, prompts):
    scores = {d: [] for d in DIMENSIONS}
    for p in prompts:
        v = model.generate(p)
        for d in DIMENSIONS:
            scores[d].append(evaluator[d](v, p))
    quality = mean(scores[d] for d in QUALITY_DIMS)
    semantic = mean(scores[d] for d in SEMANTIC_DIMS)
    return (quality + semantic) / 2, scores

def vbench2(model, prompts):
    out = {}
    for cat in CATEGORIES:
        for dim in cat.dims:
            vids = [model.generate(p) for p in prompts[dim]]
            auto = dim.evaluator(vids)      # VLM / detector
            human = human_win_ratio(vids)
            out[dim] = (auto, human, spearman(auto, human))
    return out

